// @ts-ignore `.open-next/worker.js` is generated by the OpenNext build.
import { default as handler } from "./.open-next/worker.js";

type WorkerSelfReference = {
  fetch(input: RequestInfo | URL, init?: RequestInit): Promise<Response>;
};

type ScheduledEnv = {
  WORKER_SELF_REFERENCE: WorkerSelfReference;
  CRON_SECRET?: string;
};

const SWEEP_CRON = "* * * * *";

const worker = {
  fetch: handler.fetch,

  async scheduled(controller: { cron: string }, env: ScheduledEnv) {
    if (controller.cron !== SWEEP_CRON) return;

    const secret = env.CRON_SECRET?.trim();
    if (!secret) {
      throw new Error("CRON_SECRET is not configured");
    }

    const response = await env.WORKER_SELF_REFERENCE.fetch(
      new Request("https://conventus.internal/api/jobs/sweep", {
        method: "GET",
        headers: {
          authorization: `Bearer ${secret}`
        }
      })
    );

    if (!response.ok) {
      throw new Error(`CRON_SWEEP_FAILED_${response.status}`);
    }
  }
};

export default worker;
